def calculate_total(items: List[Optional[Item]]) -> Optional[float]:
    if not items:
        return None
    return sum(item.price for item in items if item and item.price > 0)

def divide_numbers(a: float, b: float) -> float:
    if b == 0:
        raise ValueError("Cannot divide by zero")
    return a / b

# Usage
try:
    result = divide_numbers(10, 0)
except ValueError as error:
    print(error)

fn find_max(numbers: &[i32]) -> Option<i32> {
    if numbers.is_empty() {
        None
    } else {
        let mut max = numbers[0];
        for &number in numbers.iter().skip(1) {
            if number > max {
                max = number;
            }
        }
        Some(max)
    }
}

